        html: `<p>За загальним правилом державна реєстрація створення юридичної особи проводиться у строк, визначений Законом «Про державну реєстрацію юридичних осіб, фізичних осіб — підприємців та громадських формувань». Витрати складаються з адміністративного збору за окремі реєстраційні дії, нотаріальних послуг за посвідчення підписів та, за бажанням, вартості юридичного супроводу.</p>
<p>Точну вартість ми завжди прораховуємо індивідуально залежно від структури власності, наявності іноземного елемента та обраного способу подання документів, щоб клієнт бачив прозорий кошторис без прихованих платежів. Онлайн-подання зазвичай дозволяє зекономити час і частину витрат.</p>
<p>Варто враховувати, що формальна реєстрація — це лише перший крок. Реальний строк запуску бізнесу залежить також від відкриття рахунку, проходження фінансового моніторингу в банку, отримання за потреби ліцензій чи дозволів та налаштування обліку. Тому, плануючи старт, ми радимо закладати запас часу й готувати документи паралельно, а не послідовно: поки реєстратор опрацьовує заяву, можна готувати пакет для банку та внутрішні накази, аби не втрачати тижні на очікуванні.</p>`,
