<p>Остання позиція важливіша за решту. Ми починаємо роботу не з протоколу, а зі статуту: саме він визначає, хто, яким складом і в якому порядку ухвалює рішення, і саме його положення роблять процедуру простою або складною. Про перегляд статуту — у матеріалі про <a href="/blog/zminy-do-statutu-tov/">зміни до статуту ТОВ</a>.</p>
