        id: "s1",
        h2: "Перелік є виключним",
        html: `<p>Базовий акт — <strong>Закон України «Про ліцензування видів господарської діяльності» № 222-VIII від 2 березня 2015 року</strong>. Його ключова властивість: він визначає <strong>виключний перелік</strong> видів діяльності, що підлягають ліцензуванню.</p>
<p>Практичний висновок простий: <strong>якщо вашого виду діяльності немає в цьому переліку — ліцензія не потрібна</strong>, і жоден орган не може її вимагати. Спроби вимагати ліцензію поза переліком — привід для оскарження, а не для оформлення.</p>
<p>Перелік охоплює сфери, де діяльність впливає на безпеку, здоровʼя чи права споживачів: фінансові послуги, обіг окремих груп товарів, медична та освітня практика, охоронна діяльність, перевезення, поводження з відходами та низка інших. Склад переліку переглядається, тому перед запуском нового напряму його перевіряють у чинній редакції закону.</p>`,
