<p>Є й менш очевидний ризик: відсутність ліцензії ставить під сумнів <strong>дійсність укладених угод</strong> і дає контрагенту аргумент у спорі. Саме тому це одне з перших питань при <a href="/blog/due-diligence-biznesu/">due diligence перед купівлею бізнесу</a>: виявлена безліцензійна діяльність прямо знижує вартість активу або зриває угоду.</p>
