        h2: "Підстави ліквідації",
        html: `<p>Ліквідація — одна з форм припинення юридичної особи (ст. 104 ЦК), і головна її відмінність: <b>припинення без правонаступництва</b>. Після внесення запису до ЄДР компанія перестає існувати, а її права й обов'язки нікому не переходять.</p>
<p>Добровільна ліквідація належить до компетенції органу або особи, уповноваженої ухвалювати таке рішення відповідно до установчих документів (ст. 110 ЦК). Для ТОВ це загальні збори учасників, а якщо учасник один — його одноосібне рішення.</p>
<p><b>Чесна розвилка на початку:</b> повна ліквідація потрібна не завжди. Вона дає «чистий» вихід — компанія юридично зникає, обов'язки погашені, питань на майбутнє немає. Ціна цього — час (4–9 місяців) і обов'язкова податкова перевірка. Якщо компанія має непогашені боргові зобов'язання, які не покриваються майном, це вже не ліквідація, а <a href="/blog/bankrutstvo-kompanii/">банкрутство</a>, і процедура інша.</p>
<p>Контекст — практика <a href="/practices/corporate-law/">корпоративного права</a>.</p>`,
