        id: "s2",
        h2: "Типові ризики",
        html: `<p>Ризики в договірній роботі повторюються з компанії в компанію.</p>
<ul>
<li><b>Контрагент не той, за кого себе видає.</b> Відсутність повноважень у підписанта, відомості про припинення в ЄДР, банкрутство, санкції, непідтверджена ділова репутація.</li>
<li><b>Нечіткий предмет.</b> «Надання маркетингових послуг» без опису результату — класика спорів про те, чи було виконання.</li>
<li><b>Ціна без механізму зміни</b> в довгостроковому договорі, у валютних і будівельних контрактах особливо.</li>
<li><b>Строки без наслідків.</b> Строк є, а санкції за його порушення немає — умова декларативна.</li>
<li><b>Приймання без процедури.</b> Не описано, хто, як і в який строк підписує акт, і що означає мовчання.</li>
<li><b>Односторонні права лише в контрагента</b> — відмова від договору, зміна ціни, зупинення виконання.</li>
<li><b>Неузгодженість з іншими договорами</b> компанії: ви зобов'язалися перед замовником швидше, ніж ваш постачальник зобов'язався перед вами.</li>
<li><b>Відсутність підписаних додатків</b>, на які посилається основний текст.</li>
</ul>
<p>Перевірка контрагента має бути процедурою, а не доброю волею менеджера: витяг з ЄДР на дату підписання, перевірка повноважень підписанта за статутом і наказом чи довіреністю, судовий реєстр, реєстр боржників, санкційні переліки. Для великих угод це переростає в повноцінний <a href="/blog/due-diligence-biznesu/">due diligence</a>.</p>`,
