<p>І окремо — <b>перегляд портфеля договорів</b> після скасування ГК. Це разова робота, яку варто зробити один раз для довгострокових договорів: перевірити посилання на норми ГК, умови про відповідальність і процедуру розірвання. Для договорів, що закінчуються найближчим часом, цього робити не треба — вони доживуть свій строк за чинними правилами.</p>
