        h2: "Що змінилося з 28 серпня 2025 року",
        html: `<p>Разом зі скасуванням Господарського кодексу Закон № 4196-IX вніс зміни до Цивільного кодексу, які стосуються корпоративного управління. Три з них варто врахувати, коли ви однаково переписуєте статут.</p>
<ul>
<li><b>Рішення загальних зборів ухвалюються більшістю від усіх учасників</b>, а не від присутніх. Це загальне правило за замовчуванням; для змін до статуту залишається спеціальна норма про три чверті голосів усіх учасників.</li>
<li><b>Єдиний учасник може самостійно керувати ТОВ</b> — без обов'язкового окремого виконавчого органу.</li>
<li><b>Визначено фідуціарні обов'язки посадових осіб.</b> Це підвищує значення статутних положень про межі повноважень директора: про його ризики ми пишемо в матеріалі про <a href="/blog/vidpovidalnist-dyrektora-tov/">відповідальність директора ТОВ</a>.</li>
</ul>
<p>Окремо: <b>Господарський кодекс України втратив чинність 28 серпня 2025 року</b>. Якщо ваш статут містить посилання на його статті — а статути, складені до 2025 року, нерідко їх містять, — такі посилання тепер ведуть у нікуди. Сам статут від цього недійсним не стає, але це вагома причина включити приведення до чинного законодавства в найближчу нову редакцію, а не чекати окремої нагоди.</p>
<p>Те саме стосується організаційно-правових форм: Закон № 4196-IX заборонив створювати нові приватні, дочірні, іноземні, державні й комунальні підприємства, а наявні мають привести статути у відповідність протягом трирічного перехідного періоду — <b>до 28 серпня 2028 року</b>. Якщо ви працюєте у формі приватного підприємства, це не «колись», а конкретний дедлайн.</p>`,
