        html: `<p>Єдиний соціальний внесок — головне джерело неприємностей при закритті. Він нараховується <b>до дати внесення запису про припинення</b>, незалежно від того, чи велася діяльність і чи був дохід.</p>
<p>Практичний наслідок: якщо ФОП не працював два роки, але й не був закритий, за ці два роки нарахується ЄСВ у повному обсязі, ще й з пенею. Саме так утворюється більшість «раптових» боргів.</p>
<p>Після подання звітності податкова проводить остаточний розрахунок. Іноді призначається документальна перевірка — вона не є обов’язковою в кожному випадку, але право її провести в контролюючого органу залишається.</p>
<p>Зняття з обліку відбувається лише після повного погашення зобов’язань. Довідку про відсутність заборгованості варто отримати й зберегти — це єдиний зручний доказ того, що процедуру завершено.</p>`,
