<p>Розмір штрафу вимірюється десятками тисяч гривень, а за повторне порушення протягом року він зростає. Крім того, недостовірні дані в реєстрі дають банку підставу відмовити в обслуговуванні, а замовнику — відхилити тендерну пропозицію.</p>
