        html: `<p>Три форми, які найчастіше плутають на старті. Обрати треба до, а не після реєстрації — переоформлення коштує часу.</p>
<table>
<thead><tr><th></th><th>Громадська організація</th><th>Громадська спілка</th><th>Благодійна організація</th></tr></thead>
<tbody>
<tr><td>Хто засновує</td><td>фізичні особи</td><td>юридичні особи приватного права</td><td>фізичні та/або юридичні особи</td></tr>
<tr><td>Основний закон</td><td>про громадські об’єднання</td><td>про громадські об’єднання</td><td>про благодійну діяльність</td></tr>
<tr><td>Головна мета</td><td>захист прав, суспільні інтереси</td><td>те саме, але для об’єднань</td><td>надання благодійної допомоги</td></tr>
<tr><td>Типове використання</td><td>адвокація, спорт, культура, освіта, волонтерство</td><td>асоціації, галузеві об’єднання</td><td>збір і розподіл допомоги</td></tr>
</tbody>
</table>
<p>Практичне правило: якщо основна діяльність — <b>збирати кошти й передавати допомогу</b>, це благодійна організація. Якщо діяльність — <b>захищати інтереси, навчати, організовувати, просувати</b>, це громадська організація. Для об’єднання компаній однієї галузі — громадська спілка.</p>
<p>Помилка з формою на старті найчастіше проявляється при подачі на грант: донор дивиться на організаційно-правову форму й статутні цілі, і невідповідність закриває доступ до фінансування.</p>`,
