        html: `<p>Статут — головний документ організації. Для ГО він важливіший, ніж для ТОВ, бо саме на нього дивляться і податкова при наданні неприбуткового статусу, і донори при розгляді заявок на фінансування.</p>
<p>Обов’язковий мінімум змісту:</p>
<ul>
<li>найменування організації;</li>
<li>мета (цілі) та напрями діяльності;</li>
<li>порядок набуття і припинення членства, права та обов’язки членів;</li>
<li>повноваження керівника, органів управління, порядок їх формування та строк повноважень;</li>
<li>періодичність засідань і порядок ухвалення рішень;</li>
<li>порядок звітності, контролю, оскарження рішень органів;</li>
<li>джерела надходжень і порядок використання коштів та майна;</li>
<li>порядок внесення змін до статуту;</li>
<li>порядок припинення діяльності та вирішення майнових питань.</li>
</ul>
<p>Два формулювання, на які варто витратити окрему увагу:</p>
<p><b>Мета і напрями діяльності.</b> Вони мають бути достатньо широкими, щоб охопити реальні плани, і достатньо конкретними, щоб податкова побачила неприбутковий характер. Занадто вузьке формулювання доведеться змінювати щоразу, коли з’явиться новий напрям роботи.</p>
<p><b>Заборона розподілу доходів.</b> Статут має прямо передбачати, що доходи або їх частина не розподіляються серед засновників, членів, працівників (крім оплати їхньої праці), а майно при припиненні передається іншій неприбутковій організації або зараховується до бюджету. Без цієї норми неприбуткового статусу не буде — це найчастіша причина відмови.</p>`,
