        h2: "Що обрати під конкретну мету",
        html: `<p>Найпростіший спосіб визначитися — відповісти на три питання.</p>
<ol>
<li><b>Хто буде членами — компанії чи люди?</b> Компанії — громадська спілка. Люди — громадська організація. Змішаний склад можливий, але його треба прямо описати у статуті.</li>
<li><b>Чи плануєте отримувати гранти й донорське фінансування?</b> Якщо так, потрібна неприбуткова форма з відповідним статутом. Донори дивляться на організаційно-правову форму й статутні цілі раніше, ніж на все інше.</li>
<li><b>Чи буде спільна комерційна діяльність?</b> Якщо метою є спільний заробіток, громадське об’єднання — неправильний інструмент. Тут працює звичайне <a href="/blog/reyestratsiya-tov/">ТОВ</a> або <a href="/blog/kholdyngova-struktura/">група компаній</a>.</li>
</ol>
<p>У більшості випадків, з якими ми стикаємося, правильна відповідь — громадська спілка. Вона дає неприбутковий статус, дозволяє залучати гранти, підходить для представництва галузі й не створює зайвих податкових питань.</p>
<p>Одне обмеження варто перевірити ще до обговорення статуту: засновниками громадської спілки не можуть бути компанії, єдиним засновником яких є одна й та сама особа. Якщо «асоціацію» планують створити з кількох ТОВ одного власника, ця конструкція не пройде реєстрацію.</p>`,
