<p>Найнебезпечніший наслідок — <b>ретроспективність</b>. Виключення відбувається не з дати рішення податкової, а з першого числа місяця, наступного за місяцем допущеного порушення. Тобто організація дізнається, що вже кілька місяців є платником податку на прибуток, і має подати звітність та сплатити податок за цей період.</p>
