<p>Загальний строк видачі за ст. 4-1 Закону № 2806-IV — <b>десять робочих днів</b>, якщо інше не встановлено законом. Для складних дозволів спеціальні закони встановлюють довші строки, тому саме їх і треба перевіряти.</p>
