        html: `<p>Обсяг обов’язків залежить від форми ведення бізнесу, і різниця тут принципова.</p>
<p><b>ТОВ</b> зобов’язане вести повноцінний бухгалтерський облік і складати фінансову звітність. Відповідальність за організацію обліку несе керівник, а не бухгалтер — це прямо визначено законом про бухгалтерський облік.</p>
<p><b>ФОП</b> бухгалтерський облік у класичному розумінні не веде. Але це не означає «нічого не треба»: підприємець зобов’язаний вести облік доходів, а на загальній системі — і витрат, зберігати первинні документи та подавати податкову звітність. Вимога вести паперову книгу обліку скасована, сам облік — ні.</p>
<p>Найпоширеніша помилка початківців: сприймати скасування книги обліку як скасування обліку. Під час перевірки саме первинні документи підтверджують походження коштів, і без них донарахування неминучі.</p>`,
